ck.json to include new dependencies: cors, dompurify, express-rate-limit, helmet, and jsdom.","tree":{"sha":"6bc635223299e18fa3005afe8758295ee0919a95","url":"https://api.github.com/repos/mimimightyowl/live-poll-bot/git/trees/6bc635223299e18fa3005afe8758295ee0919a95"},"url":"https://api.github.com/repos/mimimightyowl/live-poll-bot/git/commits/142bca2e22c29af22f246267e32d971a7feb822b","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/63245559?v=4","events_url":"https://api.github.com/users/mimimightyowl/events{/privacy}","followers_url":"https://api.github.com/users/mimimightyowl/followers","following_url":"https://api.github.com/users/mimimightyowl/following{/other_user}","gists_url":"https://api.github.com/users/mimimightyowl/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/mimimightyowl","id":63245559,"login":"mimimightyowl","node_id":"MDQ6VXNlcjYzMjQ1NTU5","organizations_url":"https://api.github.com/users/mimimightyowl/orgs","received_events_url":"https://api.github.com/users/mimimightyowl/received_events","repos_url":"https://api.github.com/users/mimimightyowl/repos","site_admin":false,"starred_url":"https://api.github.com/users/mimimightyowl/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/mimimightyowl/subscriptions","type":"User","url":"https://api.github.com/users/mimimightyowl","user_view_type":"public"},"html_url":"https://github.com/mimimightyowl/live-poll-bot/commit/142bca2e22c29af22f246267e32d971a7feb822b","node_id":"C_kwDOQIRn9NoAKDE0MmJjYTJlMjJjMjlhZjIyZjI0NjI2N2UzMmQ5NzFhN2ZlYjgyMmI","parents":[{"html_url":"https://github.com/mimimightyowl/live-poll-bot/commit/2b3e1679933346dba122c12e5c0a3f7504d4e24c","sha":"2b3e1679933346dba122c12e5c0a3f7504d4e24c","url":"https://api.github.com/repos/mimimightyowl/live-poll-bot/commits/2b3e1679933346dba122c12e5c0a3f7504d4e24c"}],"sha":"142bca2e22c29af22f24